// The shape of the generated files in data/ (written by scripts/extract.ts, read by src/).

/** data/pool.json */
export type PoolFile = {
  generated: string;
  /** When Scryfall last updated the bulk files this was extracted from. */
  scryfall: { oracleCardsUpdatedAt: string; defaultCardsUpdatedAt: string; rulingsUpdatedAt: string };
  /** Sorted by name. */
  cards: PoolCard[];
};

/** One card's Oracle data, as Scryfall gives it (strings are not parsed here). */
export type PoolCard = {
  name: string;
  slug: string;
  oracleId: string;
  layout: string;
  /** For example "{1}{R}". Empty for a card with no mana cost, such as a land. */
  manaCost: string;
  manaValue: number;
  /** For example "Creature — Goblin", with an em dash. */
  typeLine: string;
  oracleText: string;
  /** Strings, because some cards have "*" or "1+*". Null when the card has none. */
  power: string | null;
  toughness: string | null;
  /** Scryfall's colors, which also count color-defining abilities. Checked against the derived colors in tests. */
  colors: string[];
  /** The color indicator's colors (CR 204), empty when there is none. */
  colorIndicator: string[];
  /** Keyword abilities Scryfall lists, for example ["Flying"]. */
  keywords: string[];
  /**
   * The rest describes the printing whose art is shown (D-029). Art comes from Scryfall's image hosts at runtime,
   * never bundled (D-007), and the artist is always credited.
   */
  images: { normal: string; large: string; png: string; artCrop: string };
  artist: string;
  set: string;
  collectorNumber: string;
  scryfallUri: string;
  /**
   * How the printing was chosen: "pin" (in pool.txt), "rule" (newest regular printing) or "oracleCards" (Scryfall's
   * pick). A plain string because JSON imports type strings as `string`.
   */
  printingChosenBy: string;
};

/** data/rulings/<slug>.json */
export type RulingsFile = {
  generated: string;
  name: string;
  oracleId: string;
  rulings: { source: string; publishedAt: string; comment: string }[];
};

export const GENERATED_NOTE = "Generated by `pnpm cards:extract` from Scryfall bulk data. Do not edit by hand.";

/**
 * Compares card names by their characters, not the machine's locale, so sorted output is the same everywhere
 * (with some locales, "Æther Vial" would sort after "Zombie").
 */
export function compareNames(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

/** One line of pool.txt: a card name, and optionally the printing to show (D-029). */
export type PoolEntry = { name: string; pin: PrintingPin | null };

/** `[m10]` or `[m10 146]`: a Scryfall set code, and a collector number when the set has several printings. */
export type PrintingPin = { set: string; collectorNumber: string | null };

/**
 * The entries in pool.txt, sorted by name. One card per line, optionally followed by a pin:
 * `Lightning Bolt`, `Lightning Bolt [m10]`, `Lightning Bolt [m10 146]`. Blank lines and `#` comments are ignored.
 */
export function parsePoolTxt(text: string): PoolEntry[] {
  const entries = text
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line !== "" && !line.startsWith("#"))
    .map(parsePoolLine);
  const names = entries.map((e) => e.name);
  if (new Set(names).size !== names.length) throw new Error("pool.txt lists a card twice.");
  return entries.sort((a, b) => compareNames(a.name, b.name));
}

function parsePoolLine(line: string): PoolEntry {
  const match = /^(.*?)\s*\[([a-z0-9]+)(?:\s+(\S+))?\]$/.exec(line);
  if (match === null) {
    if (line.includes("[") || line.includes("]")) {
      throw new Error(`pool.txt: can't read the pin in "${line}" (set codes are lower case, like [m10] or [m10 146])`);
    }
    return { name: line, pin: null };
  }
  const [, name = "", set = "", collectorNumber] = match;
  return { name, pin: { set, collectorNumber: collectorNumber ?? null } };
}

/** "Lightning Bolt" -> "lightning-bolt", "Æther Vial" -> "aether-vial", "Lim-Dûl's Vault" -> "lim-duls-vault". */
export function slugify(name: string): string {
  return name
    .toLowerCase()
    .replace(/æ/g, "ae")
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/['’]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
}
